  function agreements(){if(!d().versions.some(v=>v.files.length))return '<p class="hint">'+L('No agreement file is available.','暂无可读取的协议文件。')+'</p>';return '<div class="tablewrap"><table class="tbl resp ln-agreements"><thead><tr>'+[L('File','协议文件'),L('Version','版本'),L('Uploaded','上传时间'),L('Uploaded by','上传人')].map(v=>'<th>'+v+'</th>').join('')+'</tr></thead><tbody>'+d().versions.flatMap((v,vi)=>v.files.map((f,fi)=>'<tr><td data-label="'+L('File','协议文件')+'"><button class="btn-link" data-act="ln-agreement-download" data-v="'+vi+':'+fi+'" '+(!f.url?'disabled':'')+'>'+E(f.name)+'</button>'+(!f.url?'<span class="hint">'+L('Original unavailable','原文件不可用')+'</span>':'')+'</td><td data-label="'+L('Version','版本')+'">V'+(vi+1)+'</td><td data-label="'+L('Uploaded','上传时间')+'">'+time(v.at)+'</td><td data-label="'+L('Uploaded by','上传人')+'">'+E(tr(v.by))+'</td></tr>')).join('')+'</tbody></table></div>';}
  function detail(){const x=d();if(!x)return {title:L('Unavailable','业务不可用'),html:CF.empty(L('Business unavailable','业务不可用'),'')};let action=can('pay')?'pay':can('confirm')?'confirm':can('reupload')?'reupload':'';const next=x.state==='pending'?L('Funder','资金方'):x.state==='waiting'?L('Asset holder','资产方'):L('No pending disbursement action','当前无放款待办');const summary='<div class="ln-detail-hero"><div><p class="hint">'+(x.record?L('Disbursement amount','放款金额'):L('Agreed disbursement amount','约定放款金额'))+'</p><div class="ln-amount">'+amt(x.settlement,x.ccy)+'</div></div>'+CF.tag(x.state==='confirmed'?'ok':'',businessLabel(x))+'</div>'+rows([[L('Current actor','当前处理方'),next],[L('Application number','融资申请编号'),E(x.request)],[L('Business number','融资业务编号'),E(x.id)],[L('Disbursement number','放款编号'),x.record?E(x.record.id):L('No disbursement record yet','尚无放款记录')],[L('Submitted / confirmed','提交 / 确认时间'),(x.record?time(x.record.at):L('Not submitted','未提交'))+' / '+(x.confirmedAt?time(x.confirmedAt):L('Not confirmed','未确认'))]])+markers(x)+(x.state==='terminated'?CF.note('',E(x.reason||'')):'');const privateBody=party()?((x.hold?CF.note('',L('Deferred: ','暂缓原因：')+E(x.hold.text)):'')+(x.redo?CF.note('',L('Re-upload requested: ','重传原因：')+E(x.redo.text)):'')+(x.state==='waiting'?clock():'')+(x.record?card(L('Payment evidence','放款凭证与明细'),record(true)):'')+card(L('Funder’s repayment receiving account','资金方还款收款账户'),x.record?repayAccount(true):'<p class="hint">'+L('Available after the disbursement record is submitted.','提交放款记录后显示。')+'</p>')+card(L('Asset holder’s disbursement receiving account','资产方放款收款账户'),assetAccount(true))+card(L('Agreement files','协议文件'),agreements())+(x.state==='confirmed'?CF.note('',L('Receipt confirmed. Repayment information is listed on the project.','已确认到账，还款信息见项目清单。')):'')+((x.hold||x.state==='waiting')?support():'')):'<p class="hint">'+L('Accounts, evidence and agreements are available only to the financing parties.','账户、凭证与协议仅融资双方可见。')+'</p>';return {title:L('Disbursement details','融资放款详情'),html:'<div class="ln-drawer ln-stack" data-view="detail">'+(resultText?CF.note('ok',E(resultText)):'')+summary+privateBody+'</div>',foot:b('ln-close',L('Close','关闭'))};}
  function openDetail(id,{onReturn}={}){relatedReturn=onReturn||null;if(!choose(id)){CF.toast(L('Business unavailable.','业务不可用。'));return false;}if(!S.layer?.key.startsWith('ln-'))origin=rememberLayer();detailReturn=null;resultText='';confirm=null;errors={};CF.openLayer('drawer','ln-detail');return true;}
